import { writeFileSync } from "node:fs";
import path from "node:path";
import { API_REFERENCE } from "./api.js";
import { loadContext, REPO_ROOT } from "./context.js";
import { systemPrompt } from "./prompt.js";

/**
 * Writes what the developer guide shows about the planner: the API reference and the full instructions the
 * model is given, exactly as they are sent. Run after changing either:  npm run export-docs
 */
const context = loadContext({});
const out = path.join(REPO_ROOT, "docs", "planner-data.js");
writeFileSync(
  out,
  "// Generated by `npm run export-docs` in services/planner. Do not edit by hand.\n" +
    "window.SPATAIL_PLANNER = " +
    JSON.stringify({ api: API_REFERENCE, instructions: systemPrompt(context.examples), examples: context.examples.map((e) => e.request) }) +
    ";\n",
);
console.log(`Wrote ${out}`);
